<?php require_once __DIR__.'/../../includes/bootstrap.php';require_role('admin');$kid=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT * FROM kegiatan WHERE id_kegiatan=?');$q->execute([$kid]);$k=$q->fetch();if(!$k||!in_array($k['tujuan_akhir'],['kwitansi','keduanya'],true)){http_response_code(404);exit('Modul kwitansi tidak tersedia.');}$s=$pdo->prepare("SELECT ph.id_progress,ph.tanggal,p.nama_petugas,p.kecamatan,kw.id_kwitansi,kw.nominal,kw.keperluan,kw.nomor_surat_tugas,kw.tanggal_surat_tugas,kw.berangkat,kw.bulan_pengajuan_kwitansi,COALESCE(dx.jumlah_detail,0) jumlah_detail FROM progress_harian ph JOIN petugas p ON p.id_petugas=ph.id_petugas LEFT JOIN kwitansi kw ON kw.id_progress=ph.id_progress LEFT JOIN (SELECT id_progress,COUNT(*) jumlah_detail FROM detail_progress GROUP BY id_progress) dx ON dx.id_progress=ph.id_progress WHERE ph.id_kegiatan=? AND ph.tanggal BETWEEN ? AND ? ORDER BY ph.tanggal DESC,p.nama_petugas");$s->execute([$kid,$k['tanggal_mulai'],$k['tanggal_selesai']]);$rows=$s->fetchAll();page_header('Kelola Kwitansi');?><div class="card p-4 mb-3"><div class="d-flex justify-content-between flex-wrap gap-2"><div><h2 class="h5 fw-bold mb-1"><?=e($k['nama_kegiatan'])?></h2><div class="text-secondary small"><?=e($k['nomor_kegiatan'])?> · <?=format_tanggal($k['tanggal_mulai'])?> – <?=format_tanggal($k['tanggal_selesai'])?></div></div><a class="btn btn-light" href="<?=APP_BASE_URL?>/admin/kegiatan/detail.php?id=<?=$kid?>">Kembali</a></div></div><div class="card p-4 mb-3"><h3 class="h5 fw-bold">1. Siapkan Data Kwitansi</h3><p class="text-secondary">Unduh template Excel, lengkapi kolom administrasi yang diperlukan, lalu unggah kembali agar data kwitansi dapat diproses.</p><a class="btn btn-primary" href="<?=APP_BASE_URL?>/admin/kwitansi/excel.php?id=<?=$kid?>">Kelola Excel Kwitansi</a></div><div class="card p-4"><h3 class="h5 fw-bold">2. Daftar Kwitansi</h3><div class="table-responsive"><table class="table"><thead><tr><th>No</th><th>Tanggal</th><th>Nama Petugas</th><th>Kecamatan</th><th>Status Kwitansi</th><th>Nominal</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $i=>$r):$complete=$r['id_kwitansi']&&$r['jumlah_detail']>0&&$r['nominal']!==null&&trim((string)$r['keperluan'])!==''&&trim((string)$r['nomor_surat_tugas'])!==''&&$r['tanggal_surat_tugas']&&$r['berangkat']!==null&&trim((string)$r['bulan_pengajuan_kwitansi'])!=='';?><tr><td><?=$i+1?></td><td><?=format_tanggal($r['tanggal'])?></td><td><?=e($r['nama_petugas'])?></td><td><?=e($r['kecamatan'])?></td><td><span class="badge text-bg-<?=$complete?'success':'secondary'?>"><?=$complete?'Sudah Dibuat':'Belum Lengkap'?></span></td><td><?=$r['nominal']!==null?'Rp '.number_format((float)$r['nominal'],0,',','.'):'-'?></td><td><?php if($complete):?><a class="btn btn-sm btn-outline-primary" href="<?=APP_BASE_URL?>/kwitansi_pdf_sipacak.php?id=<?=$r['id_kwitansi']?>">Download PDF</a><?php else:?>-<?php endif;?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7" class="text-center text-secondary py-4">Belum ada progress pada kegiatan ini.</td></tr><?php endif;?></tbody></table></div></div><?php page_footer();
